#' Plot Spatiotemporal Cluster Detection Results
#'
#' @description Plots a spatial distribution map based on the cluster detection result matrix 
#' and spatial shapefile, visualizing distinct cluster regions alongside their constituent spatial units.
#'
#' @param clust Matrix, the indicator matrix generated by the cluster model (e.g., \code{Lambda} or significant post-test clusters).
#' @param shp.file An \code{sf} object containing spatial map data and regional IDs (must include the \code{TOWNID} column).
#'
#' @return A \code{ggplot2} map object.
#' 
#' @export
clusters_plot <- function(clust, shp.file){
  
  K <- ncol(clust)
  
  # Compute the cluster label vector assigned to each spatial point
  col.vec <- c(clust %*% c(1:K))
  col.vec <- factor(col.vec)
  
  # Define color sequence for clusters (0 represents non-cluster areas, colored white)
  col.seq <- c("white", rainbow(K))
  names(col.seq) <- c(0:K)
  
  # Process map borders: dissolve polygons by town ID, remove internal holes, and cast to multilines
  border <- shp.file
  border <- border %>%
    group_by(TOWNID) %>%
    summarise(geometry = sf::st_union(geometry)) %>%
    ungroup() %>%
    nngeo::st_remove_holes()
  
  border <- st_cast(border, to = "MULTILINESTRING")
  
  # Render thematic map using ggplot2
  p <- ggplot()
  p <- p + geom_sf(data = shp.file, aes(fill = col.vec), linewidth = 0.25, color = grey(0.4))
  p <- p + geom_sf(data = border, linewidth = 0.75, color = grey(0.1))
  p <- p + scale_fill_manual("", values = col.seq, breaks = c(1:K), labels = paste0("C",c(1:K),"(",colSums(clust),")"))
  p <- p + coord_sf() + theme_void()
  
  return(p)
}